#!/usr/bin/env python3
import sys, argparse, json, re, math, os, shlex
from datetime import datetime, timezone, timedelta
from collections import OrderedDict, defaultdict

VERSION = "ag 0.19.6"

class EvalError(Exception): pass
class QueryError(Exception): pass

MISSING = object()

# ---------- formatting ----------
def fmt_float(x):
    if math.isnan(x): return "NaN"
    if math.isinf(x): return "inf" if x > 0 else "-inf"
    if abs(x - int(x)) < 1e-12:
        return str(int(x))
    return f"{x:.2f}"

def display(v):
    if v is MISSING or v is None:
        return "None"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int) and not isinstance(v, bool):
        return str(v)
    if isinstance(v, float):
        return fmt_float(v)
    if isinstance(v, datetime):
        vv = v.astimezone(timezone.utc).replace(tzinfo=None)
        return vv.strftime("%Y-%m-%d %H:%M:%S UTC")
    if isinstance(v, list):
        return "[" + ", ".join(display(x) for x in v) + "]"
    if isinstance(v, dict):
        return "{" + ", ".join(f"{k}:{display(v[k])}" for k in sorted(v.keys(), key=str)) + "}"
    return str(v)

def jsonable(v):
    if isinstance(v, datetime): return display(v)
    if isinstance(v, dict): return {k: jsonable(val) for k,val in v.items()}
    if isinstance(v, list): return [jsonable(x) for x in v]
    if isinstance(v, float) and math.isnan(v): return None
    return v

def compact_json_obj(d, sort_keys=False):
    return json.dumps(jsonable(d), separators=(",", ":"), sort_keys=sort_keys)

def convert_atom(s):
    if s is None: return None
    if not isinstance(s, str): return s
    if s == "": return ""
    # parsed/logfmt values are aggressively converted, except malformed composites
    sl = s.strip()
    if sl.lower() == "true": return True
    if sl.lower() == "false": return False
    if sl.lower() == "null": return None
    if re.fullmatch(r"[-+]?\d+", sl):
        try: return int(sl)
        except Exception: pass
    if re.fullmatch(r"[-+]?(?:\d+\.\d*|\d*\.\d+)(?:[eE][-+]?\d+)?", sl) or re.fullmatch(r"[-+]?\d+[eE][-+]?\d+", sl):
        try: return float(sl)
        except Exception: pass
    return s

def to_num(v):
    if isinstance(v, bool): return 1 if v else 0
    if isinstance(v, (int,float)) and not isinstance(v,bool): return v
    if isinstance(v, str):
        ss = v.strip()
        try:
            if re.fullmatch(r"[-+]?\d+", ss): return int(ss)
            return float(ss)
        except Exception: pass
    raise EvalError(f"Expected numeric value, found {display(v)}")

def is_numeric(v):
    try: to_num(v); return True
    except Exception: return False

# ---------- rows ----------
class Row:
    __slots__ = ("raw", "fields")
    def __init__(self, raw="", fields=None):
        self.raw = raw
        self.fields = dict(fields) if fields else {}
    def copy(self):
        return Row(self.raw, dict(self.fields))

# ---------- utility parsing ----------
def split_top(s, sep=','):
    out=[]; buf=[]; depth=0; quote=None; esc=False; i=0
    while i < len(s):
        c=s[i]
        if quote:
            buf.append(c)
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in ('"', "'"):
                quote=c; buf.append(c)
            elif c in '([{':
                depth+=1; buf.append(c)
            elif c in ')]}':
                depth=max(0,depth-1); buf.append(c)
            elif c==sep and depth==0:
                out.append(''.join(buf).strip()); buf=[]
            else:
                buf.append(c)
        i+=1
    out.append(''.join(buf).strip())
    return [x for x in out if x!='']

def split_pipe(q):
    return split_top(q, '|')

def split_by_keyword_top(s, kw):
    # split on first keyword at top level, case-insensitive, word bounded
    depth=0; quote=None; esc=False; i=0; low=s.lower(); kwl=kw.lower()
    while i < len(s):
        c=s[i]
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in ('"', "'"): quote=c
            elif c in '([{': depth+=1
            elif c in ')]}': depth=max(0,depth-1)
            elif depth==0 and low.startswith(kwl, i):
                before = i==0 or not (s[i-1].isalnum() or s[i-1]=='_')
                afteri = i+len(kw)
                after = afteri>=len(s) or not (s[afteri].isalnum() or s[afteri]=='_')
                if before and after:
                    return s[:i].strip(), s[afteri:].strip()
        i+=1
    return s.strip(), None

def find_as_top(s):
    left,right = split_by_keyword_top(s, 'as')
    if right is not None: return left,right
    return s,None

def unquote(s):
    s=s.strip()
    if len(s)>=2 and s[0]==s[-1] and s[0] in ('"', "'"):
        try: return bytes(s[1:-1], 'utf-8').decode('unicode_escape')
        except Exception: return s[1:-1]
    return s

def strip_comments_blank(s): return s.strip()

# ---------- field paths ----------
def parse_path(expr):
    expr=expr.strip()
    # escaped field ["field name"] followed by optional path is treated as that field
    if expr.startswith('["'):
        m=re.match(r'\["((?:\\.|[^"])*)"\](.*)$', expr)
        if m:
            first=bytes(m.group(1),'utf-8').decode('unicode_escape')
            rest=m.group(2)
            parts=[first]
            expr=rest
        else: parts=[]
    else:
        m=re.match(r'[A-Za-z_][A-Za-z0-9_]*', expr)
        if not m: return [expr]
        parts=[m.group(0)]; expr=expr[m.end():]
    while expr:
        if expr.startswith('.'):
            expr=expr[1:]
            m=re.match(r'[A-Za-z_][A-Za-z0-9_]*', expr)
            if not m: break
            parts.append(m.group(0)); expr=expr[m.end():]
        elif expr.startswith('['):
            j=expr.find(']')
            if j<0: break
            idx=expr[1:j].strip()
            if len(idx)>=2 and idx[0] in ('"',"'"):
                parts.append(unquote(idx))
            else:
                try: parts.append(int(idx))
                except Exception: parts.append(idx)
            expr=expr[j+1:]
        else: break
    return parts

def get_path(fields, expr, missing_ok=False):
    parts=parse_path(expr)
    if not parts: raise EvalError(f'No value for key "{expr}"')
    cur=fields
    first=True
    for p in parts:
        if isinstance(cur, dict) and p in cur:
            cur=cur[p]
        elif isinstance(cur, list) and isinstance(p,int):
            try: cur=cur[p]
            except Exception:
                if missing_ok: return MISSING
                raise EvalError(f'No value for key "{p}"')
        else:
            if missing_ok: return MISSING
            key = p if first else p
            raise EvalError(f'No value for key "{key}"')
        first=False
    return cur

# ---------- expression parser ----------
TOKEN_RE = re.compile(r'''
    \s*(?:
    (?P<num>[-+]?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?)|
    (?P<str>"(?:\\.|[^"])*"|'(?:\\.|[^'])*')|
    (?P<op>==|!=|<>|<=|>=|&&|\|\||[()+\-*/!,<>])|
    (?P<brfield>\["(?:\\.|[^"])*"\](?:\.[A-Za-z_][A-Za-z0-9_]*|\[-?\d+\])*)|
    (?P<id>[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*|\[-?\d+\]|\["(?:\\.|[^"])*"\])*)
    )''', re.VERBOSE)

class ExprParser:
    def __init__(self, text, row, missing_ok=False):
        self.text=text.strip(); self.row=row; self.missing_ok=missing_ok; self.toks=[]; self.i=0
        pos=0
        while pos < len(self.text):
            m=TOKEN_RE.match(self.text,pos)
            if not m:
                raise EvalError(f"unrecognized expression near {self.text[pos:]}")
            pos=m.end()
            kind=m.lastgroup; val=m.group(kind)
            self.toks.append((kind,val))
        self.toks.append(('eof',''))
    def peek(self): return self.toks[self.i][1]
    def kind(self): return self.toks[self.i][0]
    def eat(self, val=None):
        t=self.toks[self.i]
        if val is not None and t[1]!=val: raise EvalError(f"Expected {val}")
        self.i+=1; return t
    def parse(self):
        if not self.text: raise EvalError("Expected an expression")
        v=self.parse_or()
        return v
    def parse_or(self):
        v=self.parse_and()
        while self.peek() in ('or','||'):
            self.eat();
            if truthy(v): self.parse_and(); v=True
            else: v=truthy(self.parse_and())
        return v
    def parse_and(self):
        v=self.parse_cmp()
        while self.peek() in ('and','&&'):
            self.eat()
            if not truthy(v): self.parse_cmp(); v=False
            else: v=truthy(self.parse_cmp())
        return v
    def parse_cmp(self):
        v=self.parse_add()
        while self.peek() in ('==','!=','<>','<=','>=','<','>'):
            op=self.eat()[1]; r=self.parse_add(); v=compare(v,r,op)
        return v
    def parse_add(self):
        v=self.parse_mul()
        while self.peek() in ('+','-'):
            op=self.eat()[1]; r=self.parse_mul()
            if op=='+': v=arith_add(v,r)
            else: v=arith_num(v,r,'-')
        return v
    def parse_mul(self):
        v=self.parse_unary()
        while self.peek() in ('*','/'):
            op=self.eat()[1]; r=self.parse_unary(); v=arith_num(v,r,op)
        return v
    def parse_unary(self):
        if self.peek() in ('!','not','NOT'):
            self.eat(); return not truthy(self.parse_unary())
        if self.peek()=='-':
            self.eat(); return -to_num(self.parse_unary())
        return self.parse_primary()
    def parse_primary(self):
        k,v=self.toks[self.i]
        if v=='(':
            self.eat('('); out=self.parse_or(); self.eat(')'); return out
        if k=='num':
            self.eat(); return float(v) if ('.' in v or 'e' in v.lower()) else int(v)
        if k=='str':
            self.eat(); return unquote(v)
        if k in ('id','brfield'):
            self.eat(); name=v
            # function call only simple id followed by (
            if self.peek()=='(' and re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', name):
                self.eat('('); args=[]
                if self.peek()!=')':
                    while True:
                        args.append(self.parse_or())
                        if self.peek()==',': self.eat(','); continue
                        break
                self.eat(')'); return call_func(name,args)
            low=name.lower()
            if low=='true': return True
            if low=='false': return False
            if low in ('null','none'): return None
            if self.missing_ok:
                return get_path(self.row.fields, name, missing_ok=True)
            return get_path(self.row.fields, name)
        raise EvalError("Expected an expression")

def truthy(v):
    if v is MISSING or v is None: return False
    if isinstance(v,bool): return v
    if isinstance(v,(int,float)): return v != 0 and not (isinstance(v,float) and math.isnan(v))
    if isinstance(v,str): return v != ""
    return True

def compare(a,b,op):
    if a is MISSING: a=None
    if b is MISSING: b=None
    # compare numerically when possible
    if is_numeric(a) and is_numeric(b):
        a=to_num(a); b=to_num(b)
    if op in ('==',): return a==b
    if op in ('!=','<>'): return a!=b
    try:
        if op=='<=': return a<=b
        if op=='>=': return a>=b
        if op=='<': return a<b
        if op=='>': return a>b
    except Exception:
        return False
    return False

def arith_add(a,b):
    if isinstance(a, datetime) and isinstance(b, timedelta): return a+b
    if isinstance(b, datetime) and isinstance(a, timedelta): return b+a
    if is_numeric(a) and is_numeric(b):
        aa=to_num(a); bb=to_num(b); return aa+bb
    return str(a)+str(b)

def arith_num(a,b,op):
    if op=='-' and isinstance(a, datetime) and isinstance(b, datetime): return (a-b).total_seconds()
    try: aa=to_num(a); bb=to_num(b)
    except EvalError:
        raise EvalError(f"Expected numeric operands, found {display(a)} {op} {display(b)}")
    if op=='-': return aa-bb
    if op=='*': return aa*bb
    if op=='/': return aa/bb if bb!=0 else float('nan')

def call_func(name,args):
    lname=name.lower()
    if lname=='if': return args[1] if truthy(args[0]) else args[2]
    if lname=='concat': return ''.join(display(a) if not isinstance(a,str) else a for a in args)
    if lname=='contains': return str(args[1]) in str(args[0])
    if lname=='length': return len(str(args[0]))
    if lname=='num': return to_num(args[0])
    if lname=='parsehex':
        s=str(args[0]).strip();
        if s.lower().startswith('0x'): s=s[2:]
        return int(s,16)
    if lname=='substring':
        s=str(args[0]); st=int(to_num(args[1])); en=int(to_num(args[2])) if len(args)>2 else None
        return s[st:en]
    if lname=='tolowercase': return str(args[0]).strip().lower()
    if lname=='touppercase': return str(args[0]).strip().upper()
    if lname=='isnull': return args[0] is None or args[0] is MISSING
    if lname=='isempty': return args[0] is None or args[0] is MISSING or str(args[0])==''
    if lname=='isblank': return args[0] is None or args[0] is MISSING or str(args[0]).strip()==''
    if lname=='isnumeric': return is_numeric(args[0])
    if lname=='now': return datetime.now(timezone.utc)
    if lname=='parsedate': return parse_date(str(args[0]))
    mathmap={
        'abs':abs,'acos':math.acos,'asin':math.asin,'atan':math.atan,'atan2':lambda a,b: math.atan2(a,b),'cbrt':lambda x: math.copysign(abs(x)**(1/3),x),
        'ceil':math.ceil,'cos':math.cos,'cosh':math.cosh,'exp':math.exp,'expm1':math.expm1,'floor':math.floor,'hypot':lambda a,b: math.hypot(a,b),
        'log':math.log,'log10':math.log10,'log1p':math.log1p,'round':round,'sin':math.sin,'sinh':math.sinh,'sqrt':math.sqrt,'tan':math.tan,'tanh':math.tanh,
        'todegrees':math.degrees,'toradians':math.radians
    }
    if lname in mathmap:
        return mathmap[lname](*[to_num(a) for a in args])
    raise EvalError(f"unknown function {name}")

def eval_expr(expr,row,missing_ok=False):
    return ExprParser(expr,row,missing_ok=missing_ok).parse()

# ---------- operators ----------
def op_json(rows, seg):
    m=re.match(r'json(?:\s+from\s+(.+))?$', seg.strip(), re.I)
    field=m.group(1).strip() if m and m.group(1) else None
    out=[]
    for r in rows:
        if field:
            try: txt=get_path(r.fields,field)
            except EvalError as e: print(f"error: {e}", file=sys.stderr); continue
        else: txt=r.raw
        try: val=json.loads(str(txt))
        except Exception:
            print(f"error: Expected JSON, found {txt}", file=sys.stderr); continue
        nr=r.copy()
        if isinstance(val, dict): nr.fields.update(val)
        else: nr.fields['_json']=val
        out.append(nr)
    return out

def parse_logfmt_text(text):
    res={}
    # A permissive scanner for key=value, quoted double strings, and bare flags.
    i=0; n=len(text)
    while i<n:
        while i<n and text[i].isspace(): i+=1
        if i>=n: break
        # key
        start=i
        while i<n and not text[i].isspace() and text[i] != '=': i+=1
        key=text[start:i]
        if not key: i+=1; continue
        val=None
        if i<n and text[i]=='=':
            i+=1
            if i<n and text[i]=='"':
                i+=1; buf=[]; esc=False
                while i<n:
                    c=text[i]; i+=1
                    if esc: buf.append(c); esc=False
                    elif c=='\\': esc=True
                    elif c=='"': break
                    else: buf.append(c)
                val=''.join(buf)
            else:
                start=i
                while i<n and not text[i].isspace(): i+=1
                val=text[start:i]
                if val=='':
                    # consume one following bare token as the value (matches common logfmt library behavior loosely)
                    save=i
                    while i<n and text[i].isspace(): i+=1
                    st=i
                    while i<n and not text[i].isspace(): i+=1
                    nxt=text[st:i]
                    if nxt and '=' not in nxt: val=nxt
                    else: i=save
