    return res

def op_logfmt(rows, seg):
    m=re.match(r'logfmt(?:\s+from\s+(.+))?$', seg.strip(), re.I)
    field=m.group(1).strip() if m and m.group(1) else None
    out=[]
    for r in rows:
        if field:
            try: txt=get_path(r.fields,field)
            except EvalError as e: print(f"error: {e}", file=sys.stderr); continue
        else: txt=r.raw
        nr=r.copy(); nr.fields.update(parse_logfmt_text(str(txt))); out.append(nr)
    return out

def pattern_to_re(pat):
    out=[]; caps=0
    star_positions=[i for i,c in enumerate(pat) if c=='*']; last_star=star_positions[-1] if star_positions else -1
