        elif c==q: break
        j+=1
    pat=unquote(rest[:j+1]); opts=rest[j+1:].strip()
    from_field=None; nodrop=False; noconvert=False; names=[]
    # parse options (order is forgiving)
    if ' nodrop' in (' '+opts.lower()): nodrop=True
    if ' noconvert' in (' '+opts.lower()): noconvert=True
    m=re.search(r'\bfrom\s+(.+?)(?=\s+as\b|\s+nodrop\b|\s+noconvert\b|$)', opts, re.I)
    if m: from_field=m.group(1).strip()
    if not regex_mode:
        m=re.search(r'\bas\s+(.+?)(?=\s+nodrop\b|\s+noconvert\b|$)', opts, re.I)
        if m: names=[x.strip() for x in m.group(1).split(',') if x.strip()]
    if regex_mode:
        try: rgx=re.compile(pat)
        except re.error as e: raise QueryError(str(e))
        names=list(rgx.groupindex.keys())
    else:
        rgx,_=pattern_to_re(pat)
    out=[]
    for r in rows:
        try: txt=str(get_path(r.fields,from_field)) if from_field else r.raw
        except EvalError as e: print(f"error: {e}", file=sys.stderr); continue
        m=rgx.search(txt)
        if not m:
            if nodrop:
                nr=r.copy()
                for nm in names: nr.fields[nm]=None
                out.append(nr)
            continue
        nr=r.copy()
        if regex_mode:
            for nm in names:
                val=m.group(nm)
                nr.fields[nm]=val if noconvert else convert_atom(val)
        else:
            vals=list(m.groups())
            for idx,nm in enumerate(names):
                val=vals[idx] if idx<len(vals) else None
                nr.fields[nm]=val if noconvert else convert_atom(val)
        out.append(nr)
    return out

def op_split(rows, seg):
    st=seg.strip()
    m=re.match(r'split(?:\(([^)]*)\))?(.*)$', st, re.I)
    infield=m.group(1).strip() if m and m.group(1) else None
    rest=m.group(2) if m else ''
    sep=','
    mo=re.search(r'\bon\s+("(?:\\.|[^"])*"|\S+)', rest, re.I)
    if mo: sep=unquote(mo.group(1))
    outfield=None
    ma=re.search(r'\bas\s+(.+)$', rest, re.I)
    if ma: outfield=ma.group(1).strip()
    if not outfield: outfield=infield if infield else '_split'
    out=[]
    for r in rows:
        try: txt=str(get_path(r.fields,infield)) if infield else r.raw
        except EvalError as e: print(f"error: {e}", file=sys.stderr); continue
        parts=[p for p in txt.split(sep) if p!=''] if sep!='' else list(txt)
        nr=r.copy(); nr.fields[outfield]=[convert_atom(p.strip('"')) for p in parts]; out.append(nr)
    return out

def op_fields(rows, seg):
    rest=seg.strip()[len('fields'):].strip()
    include=True
    if rest.lower().startswith('only '): rest=rest[5:].strip(); include=True
    elif rest.startswith('+'): rest=rest[1:].strip(); include=True
    elif rest.lower().startswith('except '): rest=rest[7:].strip(); include=False
    elif rest.startswith('-'): rest=rest[1:].strip(); include=False
    names=[x.strip() for x in rest.split(',') if x.strip()]
    topnames=[]
    for n in names:
        # fields with paths keep their top-level object in the original tool
        if n.startswith('["'): topnames.append(parse_path(n)[0])
        else: topnames.append(re.split(r'[.\[]', n)[0])
    out=[]
    for r in rows:
        nr=r.copy()
        if include:
            nr.fields={k:v for k,v in r.fields.items() if k in topnames}
        else:
            nr.fields={k:v for k,v in r.fields.items() if k not in topnames}
        out.append(nr)
    return out

def op_where(rows, seg):
    expr=seg.strip()[len('where'):].strip()
    if not expr: raise QueryError("Expected an expression")
    out=[]
    for r in rows:
        try:
            if truthy(eval_expr(expr,r)): out.append(r)
        except EvalError as e:
            print(f"error: {e}", file=sys.stderr)
    return out

def op_assign(rows, seg):
    expr,name=find_as_top(seg)
    if name is None: raise QueryError('not assignment')
    name=name.strip()
    out=[]
    for r in rows:
        try:
            val=eval_expr(expr,r)
        except EvalError as e:
            print(f"error: {e}", file=sys.stderr); continue
        nr=r.copy(); nr.fields[name]=val; out.append(nr)
    return out

def parse_date(s):
    ss=s.strip()
    fmts=["%Y-%m-%dT%H:%M:%SZ","%Y-%m-%d %H:%M:%S","%Y-%m-%dT%H:%M:%S","%Y-%m-%d"]
    for f in fmts:
        try: return datetime.strptime(ss,f).replace(tzinfo=timezone.utc)
        except Exception: pass
    try:
        dt=datetime.fromisoformat(ss.replace('Z','+00:00'))
        if dt.tzinfo is None: dt=dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except Exception:
        raise EvalError(f"Unable to parse date: {s}")

def parse_duration(s):
    m=re.fullmatch(r'(-?\d+)(ns|us|ms|s|m|h|d|w)', s.strip())
    if not m: raise QueryError('Invalid duration')
    n=int(m.group(1)); u=m.group(2)
    mult={'ns':1e-9,'us':1e-6,'ms':1e-3,'s':1,'m':60,'h':3600,'d':86400,'w':604800}[u]
    return n*mult

def op_timeslice(rows, seg):
    st=seg.strip()
    # find matching paren after timeslice(
    start=st.find('('); depth=0; quote=None; esc=False; end=-1
    for i in range(start,len(st)):
        c=st[i]
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in ('"',"'"): quote=c
            elif c=='(': depth+=1
            elif c==')':
                depth-=1
                if depth==0: end=i; break
    expr=st[start+1:end]
    rest=st[end+1:].strip().split()
    dur=rest[0] if rest else '1m'; outfield='_timeslice'
    if len(rest)>=3 and rest[1].lower()=='as': outfield=rest[2]
    sec=parse_duration(dur)
    out=[]
    for r in rows:
        try:
            dt=eval_expr(expr,r)
            if not isinstance(dt, datetime): dt=parse_date(str(dt))
            ts=dt.timestamp(); floored=math.floor(ts/sec)*sec if sec else ts
            val=datetime.fromtimestamp(floored, tz=timezone.utc)
        except Exception as e:
            print(f"error: {e}", file=sys.stderr); continue
        nr=r.copy(); nr.fields[outfield]=val; out.append(nr)
    return out

def op_total(rows, seg):
    m=re.match(r'total\((.*)\)(?:\s+as\s+(\S+))?$', seg.strip(), re.I)
    expr=m.group(1).strip(); name=m.group(2) if m and m.group(2) else '_total'
    total=0; out=[]
    for r in rows:
        try: total += to_num(eval_expr(expr,r))
        except Exception as e: print(f"error: {e}", file=sys.stderr); continue
        nr=r.copy(); nr.fields[name]=total; out.append(nr)
    return out

# ---------- aggregation ----------
def is_agg_segment(seg):
    s=seg.strip().lower()
    return bool(re.match(r'(count(\s*\(|\s|$)|sum\s*\(|min\s*\(|max\s*\(|average\s*\(|avg\s*\(|p\d+\s*\(|pct\d+\s*\(|count_distinct\s*\()', s))

def parse_agg_spec(spec):
    expr,name=find_as_top(spec)
    outname=name.strip() if name else None
    s=expr.strip()
    if re.fullmatch(r'count', s, re.I): return ('count', None, outname or '_count')
    m=re.match(r'count\((.*)\)$', s, re.I)
    if m: return ('count', m.group(1).strip(), outname or '_count')
    for op,default in [('sum','_sum'),('min','_min'),('max','_max'),('average','_average'),('avg','_average'),('count_distinct','_countDistinct')]:
        m=re.match(op+r'\((.*)\)$', s, re.I)
        if m: return (op, m.group(1).strip(), outname or default)
    m=re.match(r'pct(\d+)\((.*)\)$', s, re.I) or re.match(r'p(\d+)\((.*)\)$', s, re.I)
    if m: return ('p'+m.group(1), m.group(2).strip(), outname or ('p'+m.group(1)))
    raise QueryError('bad aggregate')

def op_aggregate(rows, seg):
    left, by = split_by_keyword_top(seg, 'by')
    specs=[parse_agg_spec(x) for x in split_top(left, ',')]
    groups=split_top(by, ',') if by else []
    state={}
    order=[]
    def init():
        d={}
        for op,expr,name in specs:
            if op=='count': d[name]=0
            elif op in ('sum',): d[name]=0
            elif op in ('min','max'): d[name]=None
            elif op in ('average','avg'): d[name]=[0,0]
            elif op.startswith('p'): d[name]=[]
            elif op=='count_distinct': d[name]=set()
        return d
    for r in rows:
        keyvals=[]; skip=False
        for g in groups:
            try: keyvals.append(eval_expr(g,r))
            except EvalError as e: print(f"error: {e}", file=sys.stderr); skip=True; break
        if skip: continue
        kt=tuple(display(v) for v in keyvals)  # stable/hashable by display
        if kt not in state:
            state[kt]=(keyvals, init()); order.append(kt)
        d=state[kt][1]
        for op,expr,name in specs:
            if op=='count':
                if expr is None: d[name]+=1
                else:
                    try:
                        if truthy(eval_expr(expr,r,missing_ok=True)): d[name]+=1
                    except Exception: pass
            elif op=='count_distinct':
                try: d[name].add(display(eval_expr(expr,r)))
                except Exception: pass
            else:
                try: val=to_num(eval_expr(expr,r))
                except Exception: continue
                if op=='sum': d[name]+=val
                elif op=='min': d[name]=val if d[name] is None or val<d[name] else d[name]
                elif op=='max': d[name]=val if d[name] is None or val>d[name] else d[name]
                elif op in ('average','avg'):
                    d[name][0]+=val; d[name][1]+=1
                elif op.startswith('p'): d[name].append(val)
    out=[]
    agg_names=[name for _,_,name in specs]
    for kt in order:
        keyvals,d=state[kt]
        fields=OrderedDict()
        for g,v in zip(groups,keyvals): fields[g]=v
        for op,expr,name in specs:
            val=d[name]
            if op in ('average','avg'):
                val=(val[0]/val[1]) if val[1] else float('nan')
            elif op.startswith('p'):
                vals=sorted(val)
                if not vals: val=None
                else:
                    pct=int(op[1:]); idx=max(0, min(len(vals)-1, math.ceil(pct/100*len(vals))-1)); val=vals[idx]
            elif op=='count_distinct': val=len(val)
            fields[name]=val
        out.append(Row('', fields))
    # default sort by aggregate values desc, then group values asc
    def sortkey(row):
        vals=[]
        for n in agg_names:
            v=row.fields.get(n)
            if isinstance(v,(int,float)): vals.append(-v if not (isinstance(v,float) and math.isnan(v)) else float('inf'))
            else: vals.append(display(v))
        vals.extend(display(row.fields.get(g)) for g in groups)
        return tuple(vals)
    out.sort(key=sortkey)
    return out

def op_sort(rows, seg):
    st=seg.strip()
    m=re.match(r'sort\s+by\s+(.+)$', st, re.I)
    if not m: return rows
    rest=m.group(1).strip(); direction='asc'
    if re.search(r'\s+desc$', rest, re.I): direction='desc'; rest=re.sub(r'\s+desc$','',rest, flags=re.I).strip()
    elif re.search(r'\s+asc$', rest, re.I): direction='asc'; rest=re.sub(r'\s+asc$','',rest, flags=re.I).strip()
    exprs=split_top(rest, ',')
    def key(r):
        vals=[]
        for e in exprs:
            try: v=eval_expr(e,r,missing_ok=True)
            except Exception: v=r.fields.get(e, MISSING)
            vals.append(to_num(v) if is_numeric(v) else display(v))
        return tuple(vals)
    return sorted(rows, key=key, reverse=(direction=='desc'))

def apply_limit(rows, seg):
    m=re.match(r'limit\s+(-?\d+)', seg.strip(), re.I)
    n=int(m.group(1))
    return rows[:n] if n>=0 else rows[n:]

# ---------- filters ----------
class FilterParser:
    def __init__(self,text):
        self.toks=self.tokenize(text); self.i=0
    def tokenize(self,s):
        toks=[]; i=0
        while i<len(s):
            if s[i].isspace(): i+=1; continue
            if s[i] in '()': toks.append(s[i]); i+=1; continue
            if s[i]=='"':
                j=i+1; esc=False
                while j<len(s):
                    if esc: esc=False
                    elif s[j]=='\\': esc=True
                    elif s[j]=='"': break
                    j+=1
                toks.append(s[i:j+1]); i=j+1; continue
            j=i
            while j<len(s) and not s[j].isspace() and s[j] not in '()|': j+=1
            toks.append(s[i:j]); i=j
        toks.append('EOF'); return toks
    def peek(self): return self.toks[self.i]
    def eat(self): t=self.toks[self.i]; self.i+=1; return t
    def parse(self): return self.parse_or()
    def parse_or(self):
        node=self.parse_and()
        while self.peek().upper()=='OR': self.eat(); rhs=self.parse_and(); node=('or',node,rhs)
        return node
    def parse_and(self):
        node=self.parse_not()
        while self.peek().upper()=='AND': self.eat(); rhs=self.parse_not(); node=('and',node,rhs)
        return node
    def parse_not(self):
        if self.peek().upper()=='NOT': self.eat(); return ('not', self.parse_not())
        if self.peek()=='(':
            self.eat(); n=self.parse_or();
            if self.peek()==')': self.eat()
            return n
        return ('term', self.eat())

def eval_filter_node(node,line):
    typ=node[0]
    if typ=='or': return eval_filter_node(node[1],line) or eval_filter_node(node[2],line)
    if typ=='and': return eval_filter_node(node[1],line) and eval_filter_node(node[2],line)
    if typ=='not': return not eval_filter_node(node[1],line)
    term=node[1]
    if term in ('EOF',''): return True
    if term=='*': return True
    if len(term)>=2 and term[0]=='"' and term[-1]=='"': return unquote(term) in line
    pat=re.escape(term).replace(r'\*','.*')
    return re.search(pat, line, re.I) is not None

def apply_filter(lines, filter_text):
    if filter_text is None or filter_text.strip()=='' or filter_text.strip()=='*':
        return [Row(line) for line in lines]
    node=FilterParser(filter_text).parse()
    return [Row(line) for line in lines if eval_filter_node(node,line)]

# ---------- aliases ----------
def load_aliases(alias_dir=None, no_alias=False):
    if no_alias: return {}
    dirs=[]
    if alias_dir: dirs=[alias_dir]
    else:
        cur=os.getcwd()
        while True:
            d=os.path.join(cur,'.agrind-aliases')
            if os.path.isdir(d): dirs.append(d)
            parent=os.path.dirname(cur)
            if parent==cur: break
            cur=parent
    aliases={}
    for d in dirs:
        try: files=[os.path.join(d,f) for f in os.listdir(d)]
        except Exception: continue
        for f in files:
            try: txt=open(f).read()
            except Exception: continue
            km=re.search(r'keyword\s*=\s*"([^"]+)"', txt)
            tm=re.search(r'template\s*=\s*"""(.*?)"""', txt, re.S) or re.search(r'template\s*=\s*"([^"]*)"', txt, re.S)
            if km and tm: aliases[km.group(1).strip()]=tm.group(1).strip()
    return aliases

# ---------- rendering ----------
def render_legacy(rows, aggregate=False):
    if aggregate:
        if not rows: return []
        cols=[]
        for r in rows:
            for k in r.fields.keys():
                if k not in cols: cols.append(k)
        widths=[]
        for c in cols:
            maxlen=max([len(c)]+[len(display(r.fields.get(c))) for r in rows])
            widths.append(maxlen+8)
        lines=[]
        lines.append(''.join((cols[i].ljust(widths[i]) if i<len(cols)-1 else cols[i]) for i in range(len(cols))))
        lines.append('-'*sum(widths))
        for r in rows:
            parts=[]
            for i,c in enumerate(cols):
                s=display(r.fields.get(c))
                parts.append(s.ljust(widths[i]) if i<len(cols)-1 else s)
            lines.append(''.join(parts))
        return lines
    else:
        if not rows: return []
        # all field keys alphabetically; rows with no fields print raw
        keys=sorted({k for r in rows for k in r.fields.keys()}, key=str)
        max_field={}
        for k in keys:
            max_field[k]=max([len(f"[{k}={display(r.fields.get(k))}]") for r in rows if k in r.fields] or [0])
        widths={k:max(max_field[k]+8, 2*len(str(k))+11) for k in keys}
        lines=[]
        for r in rows:
            if not r.fields:
                lines.append(r.raw); continue
            present=sorted(r.fields.keys(), key=str)
            parts=[]
            for i,k in enumerate(present):
                s=f"[{k}={display(r.fields.get(k))}]"
                if i < len(present)-1: parts.append(s.ljust(widths.get(k, len(s)+8)))
                else: parts.append(s)
            lines.append(''.join(parts))
        return lines

def render_logfmt(rows):
    lines=[]
    for r in rows:
        parts=[]
        for k in sorted(r.fields.keys(), key=str):
            parts.append(f"{k}={display(r.fields[k])}")
        lines.append(' '.join(parts))
    return lines

def render_json(rows, aggregate=False):
    if aggregate:
        return [json.dumps([OrderedDict((k,jsonable(v)) for k,v in r.fields.items()) for r in rows], separators=(",", ":"))]
    return [compact_json_obj({k:r.fields[k] for k in sorted(r.fields.keys(), key=str)}, sort_keys=False) for r in rows]

def render_format(rows, fmt):
    def repl_for(r):
        def repl(m):
            key=m.group(1)
            return display(r.fields.get(key, MISSING))
        return re.sub(r'\{([^{}]+)\}', repl, fmt)
    return [repl_for(r) for r in rows]

# ---------- main pipeline ----------
def run_query(query, lines, output='legacy', fmt=None, alias_dir=None, no_alias=False):
    parts=split_pipe(query or '')
    if not parts: parts=['']
    # first part is a filter unless it is an operator or empty pipe-start
    first=parts[0].strip()
    operators=[]
    known_prefixes=('json','logfmt','parse','split','fields','where','limit','sort','timeslice','total')
    if first=='' or first.lower().startswith(known_prefixes) or is_agg_segment(first) or (' as ' in first.lower()):
        filter_text='*'; operators=parts if first!='' else parts[1:]
    else:
        filter_text=first; operators=parts[1:]
    aliases=load_aliases(alias_dir,no_alias)
    expanded=[]
    for op in operators:
        st=op.strip()
        if st in aliases:
            expanded.extend(split_pipe(aliases[st]))
        else: expanded.append(op)
    rows=apply_filter(lines, filter_text)
    aggregate=False
    for seg in expanded:
        seg=seg.strip()
        if not seg: continue
        low=seg.lower()
        try:
            if low.startswith('json'): rows=op_json(rows,seg); aggregate=False
            elif low.startswith('logfmt'): rows=op_logfmt(rows,seg); aggregate=False
            elif low.startswith('parse'): rows=op_parse(rows,seg); aggregate=False
            elif low.startswith('split'): rows=op_split(rows,seg); aggregate=False
            elif low.startswith('fields'): rows=op_fields(rows,seg); aggregate=False
            elif low.startswith('where'): rows=op_where(rows,seg); aggregate=False
            elif low.startswith('limit'): rows=apply_limit(rows,seg)
            elif low.startswith('sort'): rows=op_sort(rows,seg)
            elif low.startswith('timeslice'): rows=op_timeslice(rows,seg); aggregate=False
            elif low.startswith('total'): rows=op_total(rows,seg); aggregate=False
            elif is_agg_segment(seg): rows=op_aggregate(rows,seg); aggregate=True
            elif re.search(r'\bas\b', seg): rows=op_assign(rows,seg); aggregate=False
            else:
                raise QueryError('Expected an operator')
        except QueryError as e:
            print(f"error: {e}", file=sys.stderr)
            print("Error: Failed to parse query", file=sys.stderr)
            return 1, []
    if fmt is not None: out=render_format(rows,fmt)
    elif output=='json': out=render_json(rows, aggregate)
    elif output=='logfmt': out=render_logfmt(rows)
    else: out=render_legacy(rows, aggregate)
    return 0,out

