For more details + docs, see https://github.com/rcoh/angle-grinder"""

def main(argv=None):
    argv=list(sys.argv[1:] if argv is None else argv)
    if '--help' in argv:
        print(HELP_LONG); return 0
    if '-h' in argv:
        print(HELP_SHORT); return 0
    if '--version' in argv or '-V' in argv:
        print(VERSION); return 0
    # minimal clap-like unknown option handling
    for a in argv:
        if a.startswith('--') and a not in ('--file','--format','--output','--alias-dir','--no-alias'):
            print(f"error: unexpected argument '{a}' found\n", file=sys.stderr)
            print(f"  tip: to pass '{a}' as a value, use '-- {a}'\n", file=sys.stderr)
            print("Usage: executable [OPTIONS] [QUERY]\n", file=sys.stderr)
            print("For more information, try '--help'.", file=sys.stderr)
            return 2
    file=None; output='legacy'; fmt=None; alias_dir=None; no_alias=False; query=None
    i=0
    while i<len(argv):
        a=argv[i]
        if a in ('-f','--file'):
            i+=1; file=argv[i] if i<len(argv) else None
        elif a in ('-m','--format'):
            i+=1; fmt=argv[i] if i<len(argv) else ''
        elif a in ('-o','--output'):
