    sl = s.strip()
    if sl.lower() == "true": return True
    if sl.lower() == "false": return False
    if sl.lower() == "null": return None
    if re.fullmatch(r"[-+]?\d+", sl):
        try: return int(sl)
        except Exception: pass
    if re.fullmatch(r"[-+]?(?:\d+\.\d*|\d*\.\d+)(?:[eE][-+]?\d+)?", sl) or re.fullmatch(r"[-+]?\d+[eE][-+]?\d+", sl):
        try: return float(sl)
        except Exception: pass
