    if isinstance(v, bool): return 1 if v else 0
    if isinstance(v, (int,float)) and not isinstance(v,bool): return v
    if isinstance(v, str):
        ss = v.strip()
        try:
            if re.fullmatch(r"[-+]?\d+", ss): return int(ss)
            return float(ss)
        except Exception: pass
