        if expr.startswith('.'):
            expr=expr[1:]
            m=re.match(r'[A-Za-z_][A-Za-z0-9_]*', expr)
            if not m: break
            parts.append(m.group(0)); expr=expr[m.end():]
        elif expr.startswith('['):
